// A compact orbital vault: the room itself is walkable on floor, walls, and ceiling.
box('Vault floor',[0,-.55,0],[26,1,20],materials.floor,{surface:true});
box('Vault ceiling',[0,16.55,0],[26,1,20],materials.wall,{surface:true});
box('West wall',[-13,8,0],[1,17,20],materials.wall,{surface:true});
