box('South wall',[0,8,10],[26,17,1],materials.wall,{surface:true});

// Raised stepping islands add depth and give the player landmarks on each gravity plane.
const islandA=box('Floor island A',[-5,.18,0],[4,.36,3],materials.teal,{surface:true}); addEdge(islandA,0x71fff2,.45);
const islandB=box('Floor island B',[1,.3,-3],[3,.6,3],materials.violet,{surface:true}); addEdge(islandB,0xb7a9ff,.4);
const islandC=box('Floor island C',[7,.2,3],[3,.4,4],materials.amber,{surface:true}); addEdge(islandC,0xffcf78,.38);
// Colored landing strips mounted to the east wall and the vault ceiling.
const wallPad1=box('East wall pad',[12.38,6.1,-3],[.24,2.4,4.2],materials.teal,{surface:true}); addEdge(wallPad1,0x71fff2,.55);
const wallPad2=box('East wall pad upper',[12.38,11.3,2],[.24,3.4,4.5],materials.violet,{surface:true}); addEdge(wallPad2,0xb7a9ff,.5);
const ceilingPad=box('Ceiling pad',[-1,15.95,0],[5,.2,5],materials.amber,{surface:true}); addEdge(ceilingPad,0xffcf78,.5);

// Luminous architectural ribs and navigation strips.
for(let x=-10;x<=10;x+=5) {
  const rib=box('Floor inlay',[x,.0,0],[.035,.035,17],materials.trim,{collide:false,shadow:false});
}
for(let z=-8;z<=8;z+=4) {
  box('Floor crossline',[0,.006,z],[23,.025,.035],materials.trim,{collide:false,shadow:false});
}
for(const x of [-12.44,12.44]) {
  for(const z of [-8,8]) {
    const pillar=box('Corner light',[x,8,z],[.12,15,.12],materials.glow,{collide:false,shadow:false});
  }
}
// Floating navigation chevrons, modeled as simple emissive bars.
function bar(pos,scale,rotation=0,color=materials.glow) { const m=new THREE.Mesh(new THREE.BoxGeometry(...scale),color); m.position.set(...pos); m.rotation.y=rotation; m.castShadow=false; scene.add(m); return m; }
for(let i=0;i<5;i++) { bar([-8+i*4,.04,-8],[.8,.06,.12],i%2?.35:-.35); }

// Hazard line: a clearly visible laser crossing the central floor route.
const laser=box('Laser beam',[-1,1.05,2],[.08,1.9,8],materials.laser,{collide:false,shadow:false});
const laserGlow=new THREE.PointLight(0xff174f,8,6); laserGlow.position.set(-1,1.1,2); scene.add(laserGlow);
const laserPosts=[];
for(const z of [-2,6]) {
  const post=box('Laser emitter',[-1,.3,z],[.5,.6,.5],materials.dark,{collide:false});
  const cap=box('Emitter cap',[-1,.68,z],[.24,.15,.24],materials.laser,{collide:false,shadow:false});
  laserPosts.push(post);
}

// Shards are low-poly octahedra with a small ring of light.
const shards=[];
function makeShard(name,position,color) {
  const group=new THREE.Group(); group.name=name; group.position.set(...position); scene.add(group);
  const crystal=new THREE.Mesh(new THREE.OctahedronGeometry(.42,0),new THREE.MeshStandardMaterial({color,roughness:.22,metalness:.2,emissive:color,emissiveIntensity:.75}));
  crystal.rotation.set(.15,.25,.2); crystal.castShadow=true; group.add(crystal);
  const ring=new THREE.Mesh(new THREE.TorusGeometry(.61,.025,5,28),new THREE.MeshBasicMaterial({color,transparent:true,opacity:.75})); ring.rotation.x=Math.PI/2; group.add(ring);
  const light=new THREE.PointLight(color,4,4); group.add(light);
  shards.push({group,crystal,collected:false});
}
makeShard('Shard / floor',[-5,1.5,0],0x68f7dc);
makeShard('Shard / wall',[11.2,8.2,-3],0xc09aff);
makeShard('Shard / ceiling',[-1,14.7,0],0xffca72);

// Exit portal on the far end of the floor, energized when all shards are found.
const portal=new THREE.Group(); portal.position.set(9,.08,5.2); scene.add(portal);
const portalRing=new THREE.Mesh(new THREE.TorusGeometry(1.12,.13,8,32),new THREE.MeshStandardMaterial({color:0x527186,metalness:.55,roughness:.3,emissive:0x10232b,emissiveIntensity:.7}));
portalRing.rotation.x=Math.PI/2; portalRing.position.y=1.15; portal.add(portalRing);
const portalCore=new THREE.Mesh(new THREE.CircleGeometry(.96,24),new THREE.MeshBasicMaterial({color:0x15313b,transparent:true,opacity:.7,side:THREE.DoubleSide})); portalCore.position.y=1.15; portal.add(portalCore);
const portalLight=new THREE.PointLight(0x43d3c7,2,7); portalLight.position.y=1.2; portal.add(portalLight);
for(let i=0;i<4;i++){const gem=new THREE.Mesh(new THREE.OctahedronGeometry(.12),materials.glow); gem.position.set(Math.cos(i*Math.PI/2)*1.42,1.15+Math.sin(i*Math.PI/2)*1.42,0); portal.add(gem);}

