for(let i=0;i<4;i++){const gem=new THREE.Mesh(new THREE.OctahedronGeometry(.12),materials.glow); gem.position.set(Math.cos(i*Math.PI/2)*1.42,1.15+Math.sin(i*Math.PI/2)*1.42,0); portal.add(gem);}

// Player setup
const player = new THREE.Group();
const playerBody = new THREE.Mesh(
  new THREE.BoxGeometry(0.8, 1.2, 0.8),
  new THREE.MeshStandardMaterial({ color: 0xbceff8, roughness: 0.5, metalness: 0.15, emissive: 0x123d4a, emissiveIntensity: 0.4 })
);
playerBody.castShadow = true;
playerBody.receiveShadow = true;
player.add(playerBody);
player.position.set(0, 1.85, 0);
scene.add(player);

const spawnPoint = new THREE.Vector3(0, 2.2, 0);
const gravityDir = new THREE.Vector3(0, -1, 0);
const playerVelocity = new THREE.Vector3();
const moveState = { forward: 0, right: 0 };
const look = { yaw: 0, pitch: 0 };
const playerRadius = 0.6;
let started = false;
let collected = 0;
let paused = false;

const gemCountEl = document.getElementById('gemCount');
const gravityTextEl = document.getElementById('gravityText');
const gravityIconEl = document.getElementById('gravityIcon');
const messageEl = document.getElementById('message');
const intro = document.getElementById('intro');
const winScreen = document.getElementById('win');
const restartBtn = document.getElementById('restart');
const playBtn = document.getElementById('play');
const againBtn = document.getElementById('again');
const keys = {};

function setMessage(text) {
  messageEl.textContent = text;
  messageEl.style.display = 'block';
  clearTimeout(setMessage._timer);
  setMessage._timer = setTimeout(() => { messageEl.style.display = 'none'; }, 1600);
}

function getGravityName(direction) {
  const d = direction.clone().normalize();
  if (Math.abs(d.y) > 0.8) return d.y > 0 ? 'Ceiling' : 'Floor';
  if (Math.abs(d.x) > Math.abs(d.z)) return d.x > 0 ? 'East wall' : 'West wall';
  return d.z > 0 ? 'South wall' : 'North wall';
}

function getGravityIcon(direction) {
  const d = direction.clone().normalize();
  if (Math.abs(d.y) > 0.8) return d.y > 0 ? '↑' : '↓';
  if (Math.abs(d.x) > Math.abs(d.z)) return d.x > 0 ? '→' : '←';
  return d.z > 0 ? '↓' : '↑';
}

function refreshGravityHud() {
  gravityTextEl.textContent = getGravityName(gravityDir);
  gravityIconEl.textContent = getGravityIcon(gravityDir);
}

function refreshGemHud() {
  gemCountEl.textContent = `${collected} / ${shards.length}`;
}

function resetPlayer() {
  player.position.copy(spawnPoint);
  playerVelocity.set(0, 0, 0);
  gravityDir.set(0, -1, 0);
  look.yaw = 0;
  look.pitch = 0;
  refreshGravityHud();
}

function resetLevel() {
  for (const shard of shards) {
    shard.collected = false;
    shard.group.visible = true;
    shard.group.position.y = 1.2 + (Math.sin(shard.group.position.x * 3.1 + shard.group.position.z) * 0.35);
  }
  collected = 0;
  refreshGemHud();
  resetPlayer();
  winScreen.style.display = 'none';
  setMessage('Vault reset.');
}

function attemptGravitySwitch() {
  if (!started || paused) return;

  const raycaster = new THREE.Raycaster();
  raycaster.setFromCamera(new THREE.Vector2(0, 0), camera);
  raycaster.far = 14;
  const hits = raycaster.intersectObjects(surfaces, false);
  const current = gravityDir.clone().normalize();

  let next = current.clone().multiplyScalar(-1);
  if (hits.length) {
    const hit = hits[0];
    const hitDir = hit.point.clone().sub(camera.position).normalize();
    if (hitDir.lengthSq() > 0.0001) next.copy(hitDir);
  }

  if (next.lengthSq() < 0.0001) next = current.clone().multiplyScalar(-1);
  if (next.dot(current) > 0.92) next = current.clone().multiplyScalar(-1);

  gravityDir.copy(next.normalize());
  refreshGravityHud();
  setMessage(`Gravity: ${getGravityName(gravityDir)}`);
}

function resolveSphereCollisions(position, radius) {
  for (const obj of colliders) {
    const center = obj.getWorldPosition(new THREE.Vector3());
    const half = obj.userData.half || new THREE.Vector3(0.5, 0.5, 0.5);
    const diff = position.clone().sub(center);
    const overlapX = half.x + radius - Math.abs(diff.x);
    const overlapY = half.y + radius - Math.abs(diff.y);
    const overlapZ = half.z + radius - Math.abs(diff.z);

    if (overlapX > 0 && overlapY > 0 && overlapZ > 0) {
      const axis = [
        { name: 'x', value: overlapX, sign: diff.x >= 0 ? 1 : -1 },
        { name: 'y', value: overlapY, sign: diff.y >= 0 ? 1 : -1 },
        { name: 'z', value: overlapZ, sign: diff.z >= 0 ? 1 : -1 }
      ].sort((a, b) => a.value - b.value)[0];

      if (axis.name === 'x') {
        position.x += axis.sign * (overlapX + 0.01);
      } else if (axis.name === 'y') {
        position.y += axis.sign * (overlapY + 0.01);
      } else {
        position.z += axis.sign * (overlapZ + 0.01);
      }
    }
  }
}

function updatePlayer(dt) {
  const gravity = gravityDir.clone().normalize();
  const forwardWorld = new THREE.Vector3(Math.sin(look.yaw), 0, Math.cos(look.yaw));
  const rightWorld = new THREE.Vector3(forwardWorld.z, 0, -forwardWorld.x);
  const moveVector = new THREE.Vector3();
  const planeForward = forwardWorld.clone().projectOnPlane(gravity).normalize();
  const planeRight = rightWorld.clone().projectOnPlane(gravity).normalize();

  if (moveState.forward !== 0) moveVector.addScaledVector(planeForward, moveState.forward);
  if (moveState.right !== 0) moveVector.addScaledVector(planeRight, moveState.right);

  if (moveVector.lengthSq() > 0) {
    moveVector.normalize().multiplyScalar(3.8 * dt);
    player.position.add(moveVector);
  }

  player.position.addScaledVector(gravity, 18 * dt);
  resolveSphereCollisions(player.position, playerRadius);

  if (player.position.y < -16 || player.position.length() > 40) {
    setMessage('You fell out of the vault.');
    resetPlayer();
  }

  const laserCenter = laser.getWorldPosition(new THREE.Vector3());
  const laserHalf = laser.userData.half || new THREE.Vector3(0.1, 0.95, 4);
  const laserDiff = player.position.clone().sub(laserCenter);
  if (Math.abs(laserDiff.x) <= laserHalf.x + playerRadius && Math.abs(laserDiff.y) <= laserHalf.y + playerRadius && Math.abs(laserDiff.z) <= laserHalf.z + playerRadius) {
    setMessage('Laser hit!');
    resetPlayer();
  }

  for (const shard of shards) {
    if (shard.collected) continue;
    const dist = player.position.distanceTo(shard.group.position);
    if (dist < 1.15) {
      shard.collected = true;
      shard.group.visible = false;
      collected += 1;
      refreshGemHud();
      setMessage('Shard recovered!');
      if (collected >= shards.length) {
        setMessage('Portal activated!');
      }
    }
  }

  const portalActive = collected >= shards.length;
  portalRing.material.emissive.setHex(portalActive ? 0x0ea39f : 0x10232b);
  portalRing.material.color.setHex(portalActive ? 0x87f4ed : 0x527186);
  portalLight.intensity = portalActive ? 7.5 : 2.2;
  portalCore.material.opacity = portalActive ? 0.95 : 0.45;
  portalCore.material.color.setHex(portalActive ? 0x41d3d1 : 0x15313b);

  if (portalActive && player.position.distanceTo(portal.position) < 1.5) {
    winScreen.style.display = 'grid';
    paused = true;
    document.exitPointerLock();
  }
}

function updateCamera(dt) {
  const desiredPos = player.position.clone().add(new THREE.Vector3(0, 0.7, 0)).add(gravityDir.clone().normalize().multiplyScalar(-2.8));
  camera.position.lerp(desiredPos, 0.12);

  const gravity = gravityDir.clone().normalize();
  const yawForward = new THREE.Vector3(Math.sin(look.yaw), 0, Math.cos(look.yaw));
  const lookDir = yawForward.clone().projectOnPlane(gravity).normalize();
  const lookTarget = player.position.clone().add(new THREE.Vector3(0, 0.75, 0)).add(lookDir.clone().multiplyScalar(5));
  camera.lookAt(lookTarget);
}

const clock = new THREE.Clock();

function tick() {
  const dt = Math.min(clock.getDelta(), 0.033);

  if (started && !paused) {
    updatePlayer(dt);
    updateCamera(dt);
  }

  renderer.render(scene, camera);
  requestAnimationFrame(tick);
}

window.addEventListener('keydown', (event) => {
  const code = event.code;
  keys[code] = true;

  if (code === 'KeyG' || code === 'Space') {
    event.preventDefault();
    attemptGravitySwitch();
  }

  if (code === 'KeyR') {
    resetLevel();
  }

  if (code === 'KeyZ') {
    setMessage('Gravity: ' + getGravityName(gravityDir));
  }
});

window.addEventListener('keyup', (event) => {
  keys[event.code] = false;
});

window.addEventListener('resize', () => {
  camera.aspect = innerWidth / innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(innerWidth, innerHeight);
});

window.addEventListener('mousemove', (event) => {
  if (!started || document.pointerLockElement !== renderer.domElement) return;
  look.yaw -= event.movementX * 0.0022;
  look.pitch -= event.movementY * 0.0018;
  look.pitch = THREE.MathUtils.clamp(look.pitch, -1.2, 1.2);
});

function updateInputState() {
  moveState.forward = (keys.KeyW || keys.ArrowUp ? 1 : 0) - (keys.KeyS || keys.ArrowDown ? 1 : 0);
  moveState.right = (keys.KeyD || keys.ArrowRight ? 1 : 0) - (keys.KeyA || keys.ArrowLeft ? 1 : 0);
}

window.addEventListener('keydown', updateInputState);
window.addEventListener('keyup', updateInputState);

playBtn.addEventListener('click', () => {
  intro.style.display = 'none';
  started = true;
  paused = false;
  renderer.domElement.requestPointerLock();
  setMessage('Vault online.');
});

againBtn.addEventListener('click', () => {
  winScreen.style.display = 'none';
  paused = false;
  resetLevel();
  started = true;
  renderer.domElement.requestPointerLock();
});

restartBtn.addEventListener('click', () => {
  resetLevel();
  started = true;
  paused = false;
  renderer.domElement.requestPointerLock();
});

document.addEventListener('pointerlockchange', () => {
  if (document.pointerLockElement !== renderer.domElement) {
    if (started && !paused) {
      setMessage('Pointer released. Aim and click to continue.');
    }
  }
});

// Initialize all box half extents
for (const mesh of colliders) {
  if (!mesh.userData.half) {
    const size = mesh.geometry.parameters;
    mesh.userData.half = new THREE.Vector3(
      (size.width || size.radius * 2 || 1) / 2,
      (size.height || size.depth || 1) / 2,
      (size.depth || size.width || 1) / 2
    );
  }
}

for (const shard of shards) {
  shard.group.position.y = 1.2 + Math.sin((shard.group.position.x + shard.group.position.z) * 2.5) * 0.3;
}

refreshGravityHud();
refreshGemHud();
setMessage('Awaiting entry.');
renderer.setAnimationLoop(null);
requestAnimationFrame(tick);

