const current = gravityDir.clone().normalize();

let next = current.clone().multiplyScalar(-1);
if (hits.length && hits[0].face) {
  // Gravity pulls into the surface, opposite its outward-facing normal.
  const normalMatrix = new THREE.Matrix3().getNormalMatrix(hits[0].object.matrixWorld);
  const surfaceNormal = hits[0].face.normal.clone().applyMatrix3(normalMatrix).normalize();
  next.copy(surfaceNormal).negate();
}

