286: function resolveSphereCollisions(position, radius, gravity = new THREE.Vector3(0, -1, 0)) {
287:   let supported = false;
288:   const up = gravity.clone().negate().normalize();
289:   for (const obj of colliders) {
290:     const center = obj.getWorldPosition(new THREE.Vector3());
291:     const half = obj.userData.half || new THREE.Vector3(0.5, 0.5, 0.5);
292:     const diff = position.clone().sub(center);
293:     const overlapX = half.x + radius - Math.abs(diff.x);
294:     const overlapY = half.y + radius - Math.abs(diff.y);
295:     const overlapZ = half.z + radius - Math.abs(diff.z);
296: 
297:     if (overlapX > 0 && overlapY > 0 && overlapZ > 0) {
298:       const axis = [
299:         { name: 'x', value: overlapX, sign: diff.x >= 0 ? 1 : -1 },
300:         { name: 'y', value: overlapY, sign: diff.y >= 0 ? 1 : -1 },
301:         { name: 'z', value: overlapZ, sign: diff.z >= 0 ? 1 : -1 }
302:       ].sort((a, b) => a.value - b.value)[0];
303: 
304:       const pushNormal = new THREE.Vector3(axis.name === 'x' ? axis.sign : 0, axis.name === 'y' ? axis.sign : 0, axis.name === 'z' ? axis.sign : 0);
305:       if (pushNormal.dot(up) > 0.55) supported = true;
306:       if (axis.name === 'x') {
307:         position.x += axis.sign * (overlapX + 0.01);
308:       } else if (axis.name === 'y') {
309:         position.y += axis.sign * (overlapY + 0.01);
310:       } else {
311:         position.z += axis.sign * (overlapZ + 0.01);
312:       }
313:     }
314:   }
315:   return supported;
316: }
