function resolveSphereCollisions(position, radius, gravity = new THREE.Vector3(0, -1, 0)) {
  let supported = false;
  const up = gravity.clone().negate().normalize();
  for (const obj of colliders) {
    const center = obj.getWorldPosition(new THREE.Vector3());
    const half = obj.userData.half || new THREE.Vector3(0.5, 0.5, 0.5);
    const diff = position.clone().sub(center);
    const overlapX = half.x + radius - Math.abs(diff.x);
    const overlapY = half.y + radius - Math.abs(diff.y);
    const overlapZ = half.z + radius - Math.abs(diff.z);

    if (overlapX > 0 && overlapY > 0 && overlapZ > 0) {
      const axis = [
        { name: 'x', value: overlapX, sign: diff.x >= 0 ? 1 : -1 },
        { name: 'y', value: overlapY, sign: diff.y >= 0 ? 1 : -1 },
        { name: 'z', value: overlapZ, sign: diff.z >= 0 ? 1 : -1 }
      ].sort((a, b) => a.value - b.value)[0];

      const pushNormal = new THREE.Vector3(axis.name === 'x' ? axis.sign : 0, axis.name === 'y' ? axis.sign : 0, axis.name === 'z' ? axis.sign : 0);
      if (pushNormal.dot(up) > 0.55) supported = true;
      if (axis.name === 'x') {
        position.x += axis.sign * (overlapX + 0.01);
      } else if (axis.name === 'y') {
        position.y += axis.sign * (overlapY + 0.01);
      } else {
        position.z += axis.sign * (overlapZ + 0.01);
      }
    }
  }
  return supported;
}

